package com.tytoowns.osrstrackerbridge;

import net.runelite.api.Skill;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("osrstrackerbridge")
public interface OsrsTrackerBridgeConfig extends Config
{
    @ConfigItem(
        keyName = "deviceHost",
        name = "Device IP/Host",
        description = "Example: 192.168.1.50",
        position = 0,
        hidden = true
    )
    default String deviceHost()
    {
        return "";
    }

    @ConfigItem(
        keyName = "devicePort",
        name = "Device Port",
        description = "ESP32 HTTP port (default 8080)",
        position = 1,
        hidden = true
    )
    default int devicePort()
    {
        return 8080;
    }

    @ConfigItem(
        keyName = "deviceId",
        name = "Device ID (MAC)",
        description = "Hidden paired device ID",
        position = 98,
        hidden = true
    )
    default String deviceId()
    {
        return "";
    }

    @ConfigItem(
        keyName = "showDiagnostics",
        name = "Show Developer Diagnostics",
        description = "Shows the testing suite and telemetry data in the side panel.",
        position = 2
    )
    default boolean showDiagnostics()
    {
        return false;
    }



    enum DisplayMode
    {
        FIXED_PROFILE,
        FIXED_PLAYER_AUTO_CATEGORY,
        FOLLOW_ACTIVE_SOURCE
    }

    enum GameModeChoice
    {
        NORMAL("normal", "hiscore_oldschool"),
        IRONMAN("ironman", "hiscore_oldschool_ironman"),
        HARDCORE_IRONMAN("hc_ironman", "hiscore_oldschool_hardcore_ironman"),
        ULTIMATE_IRONMAN("u_ironman", "hiscore_oldschool_ultimate"),
        GROUP_IRONMAN("group_ironman", "hiscore_oldschool"),
        GROUP_HARDCORE_IRONMAN("group_hc_ironman", "hiscore_oldschool"),
        GROUP_UNRANKED_IRONMAN("group_unranked_ironman", "hiscore_oldschool"),
        LEAGUE("league", "hiscore_oldschool_seasonal"),
        DEADMAN("deadman", "hiscore_oldschool_deadman"),
        TOURNAMENT("tournament", "hiscore_oldschool_tournament"),
        FRESH_START("fresh_start", "hiscore_oldschool_fresh_start");

        private final String gameModeKey;
        private final String endpoint;

        GameModeChoice(String gameModeKey, String endpoint)
        {
            this.gameModeKey = gameModeKey;
            this.endpoint = endpoint;
        }

        public String gameModeKey()
        {
            return gameModeKey;
        }

        public String endpoint()
        {
            return endpoint;
        }
    }

    @ConfigItem(
        keyName = "targetPlayerDisplay",
        name = "Target player",
        description = "Status only. Updated by the plugin.",
        position = 0,
        hidden = true
    )
    default String targetPlayerDisplay()
    {
        return "";
    }

    @ConfigItem(
        keyName = "targetHiscoreCategoryDisplay",
        name = "Target hiscore category",
        description = "Status only. Updated by the plugin.",
        position = 1,
        hidden = true
    )
    default String targetHiscoreCategoryDisplay()
    {
        return "";
    }

    @ConfigItem(
        keyName = "displayMode",
        name = "Display mode",
        description = "How the device chooses which profile to show.",
        position = 2,
        hidden = true
    )
    default DisplayMode displayMode()
    {
        return DisplayMode.FIXED_PLAYER_AUTO_CATEGORY;
    }

    @ConfigItem(
        keyName = "pinnedPlayer",
        name = "Pinned player",
        description = "Used by Fixed Profile and Fixed Player Auto-Switch modes.",
        position = 3,
        hidden = true
    )
    default String pinnedPlayer()
    {
        return "";
    }

    @ConfigItem(
        keyName = "pinnedGameMode",
        name = "Pinned game mode",
        description = "Used by Fixed Profile and API-only mode.",
        position = 4,
        hidden = true
    )
    default GameModeChoice pinnedGameMode()
    {
        return GameModeChoice.NORMAL;
    }

    @ConfigItem(
        keyName = "apiOnly",
        name = "API-only mode",
        description = "Ignore live plugin stats/toasts and use API + persisted data only.",
        position = 5,
        hidden = true
    )
    default boolean apiOnly()
    {
        return false;
    }


    @ConfigItem(
        keyName = "syncConfigNow",
        name = "Apply mode/profile now",
        description = "Pushes the current effective target/device mode config once, then auto-resets.",
        position = 6,
        hidden = true
    )
    default boolean syncConfigNow()
    {
        return false;
    }

    @ConfigItem(
        keyName = "setToLoggedInPlayerNow",
        name = "Set to currently logged in player",
        description = "Applies the currently logged-in player according to the active display mode, then pushes to the device. Auto-resets.",
        position = 7,
        hidden = true
    )
    default boolean setToLoggedInPlayerNow()
    {
        return false;
    }

    enum MainScreenStatChoice
    {
        BANK_TOTAL(0, "Bank Total"),
        COLLECTION_LOG(1, "Collection Log"),
        MAX_PROGRESS(2, "% to Max Level"),
        XP_TO_99(3, "XP to 99"),
        PERCENT_TO_99(8, "% to 99"),
        COMBAT_TASKS(4, "Combat Tasks"),
        QUESTS_COMPLETED(5, "Quests"),
        DIARIES(6, "Diaries"),
        HOURS_PLAYED(7, "Hours Played");

        private final int id;
        private final String label;

        MainScreenStatChoice(int id, String label) {
            this.id = id;
            this.label = label;
        }

        public int getId() { return id; }
        public String getLabel() { return label; }
    }

    @ConfigItem(
        keyName = "mainStatTop",
        name = "Main stat top",
        description = "Displayed in the top slot of the main ESP32 screen.",
        position = 8,
        hidden = true
    )
    default MainScreenStatChoice mainStatTop()
    {
        return MainScreenStatChoice.BANK_TOTAL;
    }

    @ConfigItem(
        keyName = "mainStatBottom",
        name = "Main stat bottom",
        description = "Displayed in the bottom slot of the main ESP32 screen.",
        position = 9,
        hidden = true
    )
    default MainScreenStatChoice mainStatBottom()
    {
        return MainScreenStatChoice.COLLECTION_LOG;
    }

    @ConfigItem(
        keyName = "syncMainStatsNow",
        name = "Sync main stats now",
        description = "Pushes the selected main screen stats to the device immediately.",
        position = 10,
        hidden = true
    )
    default boolean syncMainStatsNow()
    {
        return false;
    }

    @ConfigItem(
        keyName = "mainStatTopSkill",
        name = "Top stat skill",
        description = "Skill to track for the top stat if XP/Percent to 99 is selected",
        position = 11,
        hidden = true
    )
    default SkillChoice mainStatTopSkill()
    {
        return SkillChoice.ATTACK;
    }

    @ConfigItem(
        keyName = "mainStatBottomSkill",
        name = "Bottom stat skill",
        description = "Skill to track for the bottom stat if XP/Percent to 99 is selected",
        position = 12,
        hidden = true
    )
    default SkillChoice mainStatBottomSkill()
    {
        return SkillChoice.ATTACK;
    }

enum ToastTestPreset
    {
        NONE,

        SKILL_PLUS_ONE,
        SKILL_99,
        SKILL_200M,

        TOTAL_MILESTONE,

        LEVELUP_AND_99,
        LEVELUP_AND_MILESTONE,
        NINETY_NINE_AND_MILESTONE,
        NINETY_NINE_AND_MAX_TOTAL,

        FIVE_RANDOM_LEVEL_UPS,
        QUEUE_OVERFLOW,

        PREEMPT_LONG_WITH_99,
        PREEMPT_LONG_WITH_MILESTONE,

        MIXED_PRIORITY_ORDERING
    }

    enum GridSnapshotPreset
    {
        LEVEL_3,
        MAXED_99,
        MAXED_200M
    }

    enum SkillChoice
    {
        ATTACK(Skill.ATTACK),
        DEFENCE(Skill.DEFENCE),
        STRENGTH(Skill.STRENGTH),
        HITPOINTS(Skill.HITPOINTS),
        RANGED(Skill.RANGED),
        PRAYER(Skill.PRAYER),
        MAGIC(Skill.MAGIC),
        COOKING(Skill.COOKING),
        WOODCUTTING(Skill.WOODCUTTING),
        FLETCHING(Skill.FLETCHING),
        FISHING(Skill.FISHING),
        FIREMAKING(Skill.FIREMAKING),
        CRAFTING(Skill.CRAFTING),
        SMITHING(Skill.SMITHING),
        MINING(Skill.MINING),
        HERBLORE(Skill.HERBLORE),
        AGILITY(Skill.AGILITY),
        THIEVING(Skill.THIEVING),
        SLAYER(Skill.SLAYER),
        FARMING(Skill.FARMING),
        RUNECRAFT(Skill.RUNECRAFT),
        HUNTER(Skill.HUNTER),
        CONSTRUCTION(Skill.CONSTRUCTION),
        SAILING(Skill.SAILING);

        private final Skill skill;
        SkillChoice(Skill s) { this.skill = s; }
        public Skill skill() { return skill; }
    }
}

package com.tytoowns.osrstrackerbridge;

public final class PushPayload
{
    // Required
    public String player;

    // Metadata (robustness)
    public String event;     // "level_up" | "xp_tick" | "bank_update" | "snapshot" | "heartbeat" | "config_update" | "toast" | "toast_batch"
    public Long seq;         // monotonic counter (per plugin runtime)
    public long ts;          // epoch ms

    // Skill delta
    public Integer id;
    public Integer level;

    // Snapshot levels (len 25, index 0 = total level)
    public int[] levels;

    // Exact per-skill XP.
    // len 25, index 0 unused, skills are 1..24.
    public int[] skillXp;

    // Totals
    public Integer totalLevel;
    public Long totalXp;

    // Bank total (gp)
    public Long bankTotal;

    // Total account playtime, rounded down to whole hours.
    public Integer hoursPlayed;

    public Integer questsCompleted;
    public Integer questsTotal;

    public Integer combatTasksCompleted;
    public Integer combatTasksTotal;

    public Integer diariesCompleted;
    public Integer diariesTotal;

    // Collection Log.
    // Current unique items obtained / current total obtainable items.
    public Integer collectionLogCount;
    public Integer collectionLogMax;

    // Heartbeat
    public Boolean heartbeat;

    // Explicit config update / profile identity
    public String configPlayerName;
    public String hiscoreCategory;
    public String gameMode;

    public String displayMode;
    public String pinnedPlayer;
    public String pinnedGameMode;
    public String pinnedCategory;
    public Boolean apiOnly;
    public Integer mainStatTop;
    public Integer mainStatBottom;
    public Integer mainStatTopSkill;
    public Integer mainStatBottomSkill;
    // Toast/test
    public String toast;
    public Integer toastMs;
    // toast batch
    public Boolean flushLower;
    public ToastItem[] toasts;


    private static PushPayload base(String player, long seq, String event)
    {
        PushPayload p = new PushPayload();
        p.player = player;
        p.seq = seq;
        p.event = event;
        p.ts = System.currentTimeMillis();
        return p;
    }

    public static PushPayload levelUpDelta(String player, long seq, int id, int level, int totalLevel, long totalXp)
    {
        PushPayload p = base(player, seq, "level_up");
        p.id = id;
        p.level = level;
        p.totalLevel = totalLevel;
        p.totalXp = totalXp;
        return p;
    }

    public static PushPayload xpTick(
        String player,
        long seq,
        long totalXp,
        Integer totalLevelOptional,
        int[] skillXp25)
    {
        PushPayload p = base(player, seq, "xp_tick");
        p.totalXp = totalXp;
        p.totalLevel = totalLevelOptional; // nullable
        p.skillXp = skillXp25;
        return p;
    }

    public static PushPayload bankUpdate(String player, long seq, long bankTotal, String hiscoreCategory)
    {
        PushPayload p = base(player, seq, "bank_update");
        p.bankTotal = bankTotal;
        p.hiscoreCategory = hiscoreCategory;
        return p;
    }

    public static PushPayload heartbeat(String player, long seq)
    {
        PushPayload p = base(player, seq, "heartbeat");
        p.heartbeat = Boolean.TRUE;
        return p;
    }

    public static PushPayload configUpdate(
            String player,
            long seq,
            String configPlayerName,
            String hiscoreCategory,
            String gameMode,
            String displayMode,
            String pinnedPlayer,
            String pinnedGameMode,
            String pinnedCategory,
            boolean apiOnly,
            Integer mainStatTop,
            Integer mainStatBottom,
            Integer mainStatTopSkill,
            Integer mainStatBottomSkill
        )
        {
            PushPayload p = base(player, seq, "config_update");
            p.configPlayerName = configPlayerName;
            p.hiscoreCategory = hiscoreCategory;
            p.gameMode = gameMode;
            p.displayMode = displayMode;
            p.pinnedPlayer = pinnedPlayer;
            p.pinnedGameMode = pinnedGameMode;
            p.pinnedCategory = pinnedCategory;
            p.apiOnly = apiOnly ? Boolean.TRUE : Boolean.FALSE;
            p.mainStatTop = mainStatTop;
            p.mainStatBottom = mainStatBottom;
            p.mainStatTopSkill = mainStatTopSkill;
            p.mainStatBottomSkill = mainStatBottomSkill;
            return p;
        }

    public static PushPayload sourceAnnounce(String player, long seq, String hiscoreCategory, String gameMode)
    {
        PushPayload p = base(player, seq, "source_announce");
        p.hiscoreCategory = hiscoreCategory;
        p.gameMode = gameMode;
        return p;
    }

    public static PushPayload snapshot(
        String player,
        long seq,
        int[] levels25,
        int[] skillXp25,
        int totalLevel,
        long totalXp)
    {
        PushPayload p = base(player, seq, "snapshot");
        p.levels = levels25;
        p.skillXp = skillXp25;
        p.totalLevel = totalLevel;
        p.totalXp = totalXp;
        return p;
    }

    public static PushPayload toast(String player, long seq, String toast, int toastMs)
    {
        PushPayload p = base(player, seq, "toast");
        p.toast = toast;
        p.toastMs = toastMs;
        return p;
    }

    public static PushPayload toastBatch(String player, long seq, boolean flushLower, ToastItem[] toasts,
                                         Integer totalLevelOptional, Long totalXpOptional)
    {
        PushPayload p = base(player, seq, "toast_batch");
        p.flushLower = flushLower ? Boolean.TRUE : Boolean.FALSE;
        p.toasts = toasts;
        p.totalLevel = totalLevelOptional;
        p.totalXp = totalXpOptional;
        return p;
    }

}

package com.tytoowns.osrstrackerbridge;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.PluginPanel;
import javax.swing.text.DefaultCaret;

public class ScreenOfKnowledgeBridgePanel extends PluginPanel
{
    private final ScreenOfKnowledgeBridgePlugin plugin;

    private final JComboBox<OsrsTrackerBridgeConfig.DisplayMode> displayModeDropdown;
    private final JTextField pinnedPlayerField;
    private final JComboBox<OsrsTrackerBridgeConfig.GameModeChoice> pinnedGameModeDropdown;
    private final javax.swing.JCheckBox apiOnlyCheckbox;

    private final JPanel displayModeLabelRow;
    private final JPanel displayModeFieldRow;

    private final JPanel pinnedPlayerLabelRow;
    private final JPanel pinnedPlayerFieldRow;
    private final JPanel pinnedGameModeLabelRow;
    private final JPanel pinnedGameModeFieldRow;

    private final JTextArea apiOnlyDescription;
    private final JTextArea displayModeDescription;

    private final JTextArea deviceStatusSummaryLabel;
    private final JComboBox<OsrsTrackerBridgeConfig.MainScreenStatChoice> mainStatTopDropdown;
    private final JComboBox<OsrsTrackerBridgeConfig.MainScreenStatChoice> mainStatBottomDropdown;
    private final JComboBox<OsrsTrackerBridgeConfig.SkillChoice> mainStatTopSkillDropdown;
    private final JComboBox<OsrsTrackerBridgeConfig.SkillChoice> mainStatBottomSkillDropdown;
    private final JPanel mainStatTopSkillRow;
    private final JPanel mainStatBottomSkillRow;
    private final JTextArea currentPlayerValueLabel;
    private final JTextArea currentHiscoreCategoryValueLabel;
    private final JTextArea currentModeValueLabel;

    private final JTextArea statusLabel;
    private boolean suppressEvents = false;

    private JPanel diagnosticsWrapper;
    private JPanel telemetryWrapper;
    private JPanel diagnosticsSeparator;
    private JPanel telemetrySeparator;

    public ScreenOfKnowledgeBridgePanel(ScreenOfKnowledgeBridgePlugin plugin)
    {
        this.plugin = plugin;

        setLayout(new BorderLayout());
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        JPanel root = new JPanel(new GridBagLayout());
        GridBagConstraints gbc = new GridBagConstraints();
        gbc.gridx = 0;
        gbc.gridy = 0;
        gbc.weightx = 1.0;
        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.anchor = GridBagConstraints.NORTHWEST;
        gbc.insets = new Insets(0, 0, 6, 0);

        // Title
        root.add(makeTitleLabel("Screen Of Knowledge Bridge"), gbc);

        // --------------------
        // Connection & Pairing (Top Priority)
        // --------------------
        gbc.gridy++;
        root.add(makeSeparator(), gbc);

        gbc.gridy++;
        root.add(makeSectionHeader("Device Connection & Pairing"), gbc);

        gbc.gridy++;
        statusLabel = makeWrappingValueText("Status: Not Paired", new Color(255, 85, 85));
        root.add(wrapRow(statusLabel), gbc);

        gbc.gridy++;
        root.add(makeSectionDescription("Enter the 6-digit PIN from your device screen to pair automatically."), gbc);

        gbc.gridy++;
        JPanel pairRow = new JPanel(new GridBagLayout());
        pairRow.setOpaque(false);
        GridBagConstraints pgbc = new GridBagConstraints();
        pgbc.gridx = 0; pgbc.gridy = 0; pgbc.weightx = 0.6; pgbc.fill = GridBagConstraints.HORIZONTAL; pgbc.insets = new Insets(0, 0, 0, 4);

        JTextField pinField = new JTextField();
            pinField.setHorizontalAlignment(JTextField.CENTER);
            pinField.setEditable(true);
            pinField.setFocusable(true);

            // Autofill if already paired
            if (plugin.uiGetDeviceId() != null && !plugin.uiGetDeviceId().isEmpty()) {
                pinField.setText("******");
            }

            pairRow.add(pinField, pgbc);

            pgbc.gridx = 1; pgbc.weightx = 0.4; pgbc.insets = new Insets(0, 4, 0, 0);
            JButton pairButton = new JButton("Pair");
            pairButton.addActionListener(e -> {
                String pin = pinField.getText().trim();
                if (pin.length() == 6) {
                    plugin.uiSetPanelStatus("Pairing...");
                    plugin.triggerPairing(pin);
                } else {
                    plugin.uiSetPanelStatus("PIN must be 6 digits.");
                }
            });
            pairRow.add(pairButton, pgbc);
            root.add(wrapRow(pairRow), gbc);

        // --------------------
        // Quick Action
        // --------------------
        gbc.gridy++;
        root.add(makeSeparator(), gbc);

        gbc.gridy++;
        root.add(makeSectionHeader("Quick Profile Setup"), gbc);

        gbc.gridy++;
        JButton setLoggedInButton = new JButton("Apply Active Game Account");
            setLoggedInButton.addActionListener(e -> plugin.uiSetToLoggedInPlayerNow());
            root.add(setLoggedInButton, gbc);

            gbc.gridy++;
            root.add(makeSectionDescription("Instantly syncs the device target to whichever OSRS account is currently active in RuneLite."), gbc);

        // --------------------
        // Advanced Device Profile
        // --------------------
        gbc.gridy++;
        root.add(makeSeparator(), gbc);

        gbc.gridy++;
        root.add(makeSectionHeader("Device Profile Settings"), gbc);

        gbc.gridy++;
        apiOnlyCheckbox = new javax.swing.JCheckBox("API-only mode");
        apiOnlyCheckbox.setOpaque(false);
        apiOnlyCheckbox.setForeground(Color.WHITE);
        apiOnlyCheckbox.addActionListener(e ->
        {
            if (suppressEvents) return;
            plugin.uiSetApiOnly(apiOnlyCheckbox.isSelected());
            updateDeviceConfigVisibility();
        });
        root.add(apiOnlyCheckbox, gbc);

        gbc.gridy++;
        apiOnlyDescription = makeSectionDescription("");
        root.add(apiOnlyDescription, gbc);

        gbc.gridy++;
        displayModeLabelRow = wrapRow(makeFieldLabel("Display mode"));
        root.add(displayModeLabelRow, gbc);

        gbc.gridy++;
        displayModeDropdown = new JComboBox<>(OsrsTrackerBridgeConfig.DisplayMode.values());
        displayModeDropdown.setRenderer((list, value, index, isSelected, cellHasFocus) ->
        {
            JLabel label = new JLabel(displayModeText(value));
            label.setOpaque(true);
            label.setBackground(isSelected ? list.getSelectionBackground() : list.getBackground());
            label.setForeground(isSelected ? list.getSelectionForeground() : list.getForeground());
            return label;
        });
        displayModeDropdown.addActionListener(e ->
        {
            if (suppressEvents) return;
            OsrsTrackerBridgeConfig.DisplayMode mode = (OsrsTrackerBridgeConfig.DisplayMode) displayModeDropdown.getSelectedItem();
            plugin.uiSetDisplayMode(mode);
            updateDeviceConfigVisibility();
        });
        displayModeFieldRow = wrapRow(displayModeDropdown);
        root.add(displayModeFieldRow, gbc);

        gbc.gridy++;
        displayModeDescription = makeSectionDescription("");
        root.add(displayModeDescription, gbc);

        gbc.gridy++;
        pinnedPlayerLabelRow = wrapRow(makeFieldLabel("Pinned player"));
        root.add(pinnedPlayerLabelRow, gbc);

        gbc.gridy++;
        pinnedPlayerField = new JTextField();
        pinnedPlayerField.getDocument().addDocumentListener(new DocumentListener()
        {
            @Override public void insertUpdate(DocumentEvent e) { push(); }
            @Override public void removeUpdate(DocumentEvent e) { push(); }
            @Override public void changedUpdate(DocumentEvent e) { push(); }
            private void push() { if (!suppressEvents) plugin.uiSetPinnedPlayer(pinnedPlayerField.getText()); }
        });
        pinnedPlayerFieldRow = wrapRow(pinnedPlayerField);
        root.add(pinnedPlayerFieldRow, gbc);

        gbc.gridy++;
        pinnedGameModeLabelRow = wrapRow(makeFieldLabel("Pinned game mode"));
        root.add(pinnedGameModeLabelRow, gbc);

        gbc.gridy++;
        pinnedGameModeDropdown = new JComboBox<>(OsrsTrackerBridgeConfig.GameModeChoice.values());
        pinnedGameModeDropdown.setRenderer((list, value, index, isSelected, cellHasFocus) ->
        {
            JLabel label = new JLabel(gameModeText(value));
            label.setOpaque(true);
            label.setBackground(isSelected ? list.getSelectionBackground() : list.getBackground());
            label.setForeground(isSelected ? list.getSelectionForeground() : list.getForeground());
            return label;
        });
        pinnedGameModeDropdown.addActionListener(e ->
        {
            if (suppressEvents) return;
            OsrsTrackerBridgeConfig.GameModeChoice choice = (OsrsTrackerBridgeConfig.GameModeChoice) pinnedGameModeDropdown.getSelectedItem();
            plugin.uiSetPinnedGameMode(choice);
        });
        pinnedGameModeFieldRow = wrapRow(pinnedGameModeDropdown);
        root.add(pinnedGameModeFieldRow, gbc);

        gbc.gridy++;
        JButton applyModeProfileButton = new JButton("Save & Apply to Device");
        applyModeProfileButton.addActionListener(e -> plugin.uiApplyModeProfileNow());
        root.add(applyModeProfileButton, gbc);

        // --------------------
        // Main Screen Stats
        // --------------------
        gbc.gridy++;
        root.add(makeSeparator(), gbc);

        gbc.gridy++;
        root.add(makeSectionHeader("Main Screen Stats"), gbc);

        gbc.gridy++;
        root.add(makeSectionDescription("Choose what is displayed in the two configurable stat rows at the bottom of the device screen."), gbc);

        gbc.gridy++;
        root.add(wrapRow(makeFieldLabel("Top stat row")), gbc);

        gbc.gridy++;
        mainStatTopDropdown = new JComboBox<>(OsrsTrackerBridgeConfig.MainScreenStatChoice.values());
        mainStatTopDropdown.setRenderer((list, value, index, isSelected, cellHasFocus) -> {
            JLabel label = new JLabel(value != null ? value.getLabel() : "");
            label.setOpaque(true);
            label.setBackground(isSelected ? list.getSelectionBackground() : list.getBackground());
            label.setForeground(isSelected ? list.getSelectionForeground() : list.getForeground());
            return label;
        });
        mainStatTopDropdown.addActionListener(e -> {
            if (suppressEvents) return;
            plugin.uiSetMainStatTop((OsrsTrackerBridgeConfig.MainScreenStatChoice) mainStatTopDropdown.getSelectedItem());
            updateMainStatsVisibility();
        });
        root.add(wrapRow(mainStatTopDropdown), gbc);

        gbc.gridy++;
        mainStatTopSkillDropdown = new JComboBox<>(OsrsTrackerBridgeConfig.SkillChoice.values());
        mainStatTopSkillDropdown.setRenderer((list, value, index, isSelected, cellHasFocus) -> {
            JLabel label = new JLabel(value != null ? value.name() : "");
            label.setOpaque(true);
            label.setBackground(isSelected ? list.getSelectionBackground() : list.getBackground());
            label.setForeground(isSelected ? list.getSelectionForeground() : list.getForeground());
            return label;
        });
        mainStatTopSkillDropdown.addActionListener(e -> {
            if (suppressEvents) return;
            plugin.uiSetMainStatTopSkill((OsrsTrackerBridgeConfig.SkillChoice) mainStatTopSkillDropdown.getSelectedItem());
