    public void refreshFromPlugin()
    {
        suppressEvents = true;
        try
        {
            displayModeDropdown.setSelectedItem(plugin.uiGetDisplayMode());
            pinnedPlayerField.setText(plugin.uiGetPinnedPlayer());
            pinnedGameModeDropdown.setSelectedItem(plugin.uiGetPinnedGameMode());
            apiOnlyCheckbox.setSelected(plugin.uiIsApiOnly());
            mainStatTopDropdown.setSelectedItem(plugin.uiGetMainStatTop());
            mainStatBottomDropdown.setSelectedItem(plugin.uiGetMainStatBottom());
            mainStatTopSkillDropdown.setSelectedItem(plugin.uiGetMainStatTopSkill());
            mainStatBottomSkillDropdown.setSelectedItem(plugin.uiGetMainStatBottomSkill());
        }
        finally
        {
            suppressEvents = false;
        }

        currentPlayerValueLabel.setText("Client Player: " + valueOrDash(plugin.uiGetCurrentPlayerName()));
        currentHiscoreCategoryValueLabel.setText("Hiscore Category: " + valueOrDash(plugin.uiGetCurrentHiscoreCategoryDisplay()));
        currentModeValueLabel.setText("Client Mode: " + valueOrDash(plugin.uiGetCurrentModeDisplay()));

        updateDeviceConfigVisibility();
        refreshDeviceStatusBlock();
        updateMainStatsVisibility();

        boolean showDiag = plugin.uiShowDiagnostics();
        if (diagnosticsWrapper != null) diagnosticsWrapper.setVisible(showDiag);
        if (diagnosticsSeparator != null) diagnosticsSeparator.setVisible(showDiag);
        if (telemetryWrapper != null) telemetryWrapper.setVisible(showDiag);
        if (telemetrySeparator != null) telemetrySeparator.setVisible(showDiag);
    }

    public void setStatusText(String text)
    {
        String state = text == null ? "idle" : text.trim();
        statusLabel.setText("Status: " + (state.isEmpty() ? "idle" : state));

        // Color coding for pairing and connection states
        if (state.contains("Connected") || state.contains("OK")) {
            statusLabel.setForeground(new Color(0, 200, 0)); // Green
        } else if (state.contains("Searching") || state.contains("Pairing") || state.contains("Connecting")) {
            statusLabel.setForeground(new Color(255, 170, 0)); // Orange
        } else if (state.contains("Lost") || state.contains("Failed") || state.contains("Not Paired")) {
            statusLabel.setForeground(new Color(255, 85, 85)); // Red
        } else {
            statusLabel.setForeground(Color.WHITE);
        }
    }

    public void refreshDeviceStatusBlock()
    {
        String mode = plugin.uiGetDeviceDisplayMode();
        String targetPlayer = plugin.uiGetDeviceTargetPlayer();
        String targetCategory = plugin.uiGetDeviceTargetCategory();
        String visiblePlayer = plugin.uiGetDeviceVisiblePlayer();
        String visibleCategory = plugin.uiGetDeviceVisibleCategory();

        deviceStatusSummaryLabel.setText("Target: " + pairOrDash(targetPlayer, targetCategory) + " | Vis: " + pairOrDash(visiblePlayer, visibleCategory));

        currentPlayerValueLabel.setText("Client Player: " + valueOrDash(plugin.uiGetCurrentPlayerName()));
        currentHiscoreCategoryValueLabel.setText("Hiscore Category: " + valueOrDash(plugin.uiGetCurrentHiscoreCategoryDisplay()));
        currentModeValueLabel.setText("Client Mode: " + valueOrDash(plugin.uiGetCurrentModeDisplay()));

        revalidate();
        repaint();
    }

    private JPanel wrapRow(java.awt.Component component)
    {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setOpaque(false);
        panel.add(component, BorderLayout.CENTER);
        panel.setAlignmentX(LEFT_ALIGNMENT);
        return panel;
    }

    private JTextArea makeValueLabel(String text)
    {
        return makeWrappingValueText(text, Color.LIGHT_GRAY);
    }

    private JTextArea makeWrappingValueText(String text, Color color)
    {
        JTextArea area = new JTextArea(text);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setEditable(false);
        area.setFocusable(false);
        area.setOpaque(false);
        area.setBorder(null);
        area.setForeground(color);
        area.setFont(new JLabel().getFont());

        DefaultCaret caret = (DefaultCaret) area.getCaret();
        caret.setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
        area.setCaretPosition(0);

        return area;
    }

    private String valueOrDash(String value)
    {
        if (value == null || value.trim().isEmpty()) return "-";
        return value.trim();
    }

    private String pairOrDash(String left, String right)
    {
        boolean hasLeft = left != null && !left.trim().isEmpty();
        boolean hasRight = right != null && !right.trim().isEmpty();
        if (!hasLeft && !hasRight) return "-";
        if (!hasLeft) return right.trim();
        if (!hasRight) return left.trim();
        return left.trim() + " / " + right.trim();
    }

    private void updateMainStatsVisibility()
    {
        OsrsTrackerBridgeConfig.MainScreenStatChoice topChoice = (OsrsTrackerBridgeConfig.MainScreenStatChoice) mainStatTopDropdown.getSelectedItem();
        boolean showTopSkill = topChoice == OsrsTrackerBridgeConfig.MainScreenStatChoice.XP_TO_99 || topChoice == OsrsTrackerBridgeConfig.MainScreenStatChoice.PERCENT_TO_99;
        mainStatTopSkillRow.setVisible(showTopSkill);

        OsrsTrackerBridgeConfig.MainScreenStatChoice bottomChoice = (OsrsTrackerBridgeConfig.MainScreenStatChoice) mainStatBottomDropdown.getSelectedItem();
        boolean showBottomSkill = bottomChoice == OsrsTrackerBridgeConfig.MainScreenStatChoice.XP_TO_99 || bottomChoice == OsrsTrackerBridgeConfig.MainScreenStatChoice.PERCENT_TO_99;
        mainStatBottomSkillRow.setVisible(showBottomSkill);

        revalidate();
        repaint();
    }

    private void updateDeviceConfigVisibility()
    {
        boolean apiOnly = plugin.uiIsApiOnly();
        OsrsTrackerBridgeConfig.DisplayMode mode = plugin.uiGetDisplayMode();

        boolean showDisplayMode = !apiOnly;
        boolean showPinnedPlayer = false;
        boolean showPinnedGameMode = false;

        if (apiOnly)
        {
            showPinnedPlayer = true;
            showPinnedGameMode = true;
        }
        else
        {
            switch (mode)
            {
                case FIXED_PROFILE:
                    showPinnedPlayer = true;
                    showPinnedGameMode = true;
                    break;
                case FIXED_PLAYER_AUTO_CATEGORY:
                    showPinnedPlayer = true;
                    showPinnedGameMode = false;
                    break;
                case FOLLOW_ACTIVE_SOURCE:
                    showPinnedPlayer = false;
                    showPinnedGameMode = false;
                    break;
                default:
                    showPinnedPlayer = true;
                    showPinnedGameMode = false;
                    break;
            }
        }

        displayModeLabelRow.setVisible(showDisplayMode);
        displayModeFieldRow.setVisible(showDisplayMode);
        displayModeDescription.setVisible(showDisplayMode);

        pinnedPlayerLabelRow.setVisible(showPinnedPlayer);
        pinnedPlayerFieldRow.setVisible(showPinnedPlayer);
        pinnedGameModeLabelRow.setVisible(showPinnedGameMode);
        pinnedGameModeFieldRow.setVisible(showPinnedGameMode);

        apiOnlyDescription.setText("API-only mode ignores live plugin events and forces local API profile pulling.");
        displayModeDescription.setText(getDisplayModeDescriptionText(mode));

        revalidate();
        repaint();
    }

    private String displayModeText(OsrsTrackerBridgeConfig.DisplayMode mode)
    {
        if (mode == null) return "";
        switch (mode)
        {
            case FIXED_PROFILE: return "Fixed profile";
            case FIXED_PLAYER_AUTO_CATEGORY: return "Fixed player, auto category";
            case FOLLOW_ACTIVE_SOURCE: return "Follow active source";
            default: return mode.name();
        }
    }

    private String gameModeText(OsrsTrackerBridgeConfig.GameModeChoice mode)
    {
        if (mode == null) return "";
        switch (mode)
        {
            case NORMAL: return "Normal";
            case IRONMAN: return "Ironman";
            case HARDCORE_IRONMAN: return "Hardcore Ironman";
            case ULTIMATE_IRONMAN: return "Ultimate Ironman";
            case GROUP_IRONMAN: return "Group Ironman";
            case GROUP_HARDCORE_IRONMAN: return "Group HC Ironman";
            case GROUP_UNRANKED_IRONMAN: return "Group Unranked Ironman";
            case LEAGUE: return "League";
            case DEADMAN: return "Deadman";
            case TOURNAMENT: return "Tournament";
            case FRESH_START: return "Fresh Start";
            default: return mode.name();
        }
    }

    private String getDisplayModeDescriptionText(OsrsTrackerBridgeConfig.DisplayMode mode)
    {
        if (mode == null) return "";
        switch (mode)
        {
            case FIXED_PROFILE: return "Always shows one specific player and profile.";
            case FIXED_PLAYER_AUTO_CATEGORY: return "Shows a pinned player, auto-detecting their active league/iron status.";
            case FOLLOW_ACTIVE_SOURCE: return "Automatically follows whichever RuneLite client is actively logged in.";
            default: return "";
        }
    }

