    // ---- config toggles ----
    @Subscribe
    public void onConfigChanged(ConfigChanged e)
    {
        if (!"osrstrackerbridge".equals(e.getGroup()))
        {
            return;
        }


        if (CONFIG_KEY_TARGET_PLAYER_DISPLAY.equals(e.getKey())
            || CONFIG_KEY_TARGET_HISCORE_CATEGORY_DISPLAY.equals(e.getKey()))
        {
            return;
        }

        if (CONFIG_KEY_DISPLAY_MODE.equals(e.getKey())
            || CONFIG_KEY_PINNED_PLAYER.equals(e.getKey())
            || CONFIG_KEY_PINNED_GAME_MODE.equals(e.getKey())
            || CONFIG_KEY_API_ONLY.equals(e.getKey()))
        {
            scheduleTargetRefreshAndConfigSync(false);
        }
        else if (CONFIG_KEY_SET_TO_LOGGED_IN_PLAYER_NOW.equals(e.getKey()) && "true".equals(e.getNewValue()))
        {
            uiSetToLoggedInPlayerNow();
            configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY_SET_TO_LOGGED_IN_PLAYER_NOW, false);
        }
        else if (CONFIG_KEY_SYNC_CONFIG_NOW.equals(e.getKey()) && "true".equals(e.getNewValue()))
        {
            uiApplyModeProfileNow();
            configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY_SYNC_CONFIG_NOW, false);
        }
        else if ("syncMainStatsNow".equals(e.getKey()) && "true".equals(e.getNewValue()))
        {
            uiApplyMainStatsNow();
            configManager.setConfiguration(CONFIG_GROUP, "syncMainStatsNow", false);
        }
        else if ("showDiagnostics".equals(e.getKey()))
        {
            if (sidePanel != null) {
                sidePanel.refreshFromPlugin();
            }
        }
    }

    public void sendSpoofedGrid(OsrsTrackerBridgeConfig.GridSnapshotPreset preset)
    {
        String player = getPushPlayer();
        if (player == null) player = "TestPlayer";
        HttpUrl url = buildUrl("push");
        if (url == null) return;

        int[] levels = new int[25];
        int[] xp = new int[25];
        int totalLvl = 0;
        long totalXp = 0;

        if (preset == OsrsTrackerBridgeConfig.GridSnapshotPreset.LEVEL_3) {
            for (int i = 1; i < 25; i++) { levels[i] = 1; xp[i] = 0; }
            levels[4] = 10; xp[4] = 1154; // Hitpoints is index 4
        } else if (preset == OsrsTrackerBridgeConfig.GridSnapshotPreset.MAXED_99) {
            for (int i = 1; i < 25; i++) { levels[i] = 99; xp[i] = 13034431; }
        } else if (preset == OsrsTrackerBridgeConfig.GridSnapshotPreset.MAXED_200M) {
            for (int i = 1; i < 25; i++) { levels[i] = 99; xp[i] = 200000000; }
        }

        for (int i = 1; i < 25; i++) {
            totalLvl += levels[i];
            totalXp += xp[i];
        }

        // The ESP32 firmware explicitly reads index 0 of the levels array for the Total Level display!
        levels[0] = totalLvl;

        PushPayload p = PushPayload.snapshot(player, nextSeq(), levels, xp, totalLvl, totalXp);
        enqueue(PendingKind.SNAPSHOT, url, p);
    }



    public void sendSpoofedBadge(OsrsTrackerBridgeConfig.GameModeChoice mode)
    {
        String player = getPushPlayer();
        if (player == null) player = "TestPlayer";
        HttpUrl url = buildUrl("push");
        if (url == null) return;

        PushPayload p = PushPayload.sourceAnnounce(player, nextSeq(), mode.endpoint(), mode.gameModeKey());
        enqueue(PendingKind.CONFIG, url, p);
    }

