    public void runToastTestPreset(OsrsTrackerBridgeConfig.ToastTestPreset preset, Skill s1, Skill s2, int milestoneParam, int totalActualParam, int countParam)
    {
        uiSetPanelStatus("Sending selected toast test...");
        if (preset == null || preset == OsrsTrackerBridgeConfig.ToastTestPreset.NONE)
        {
            return;
        }

        final String n1 = skillName(s1);
        final String n2 = skillName(s2);

        final int milestone = clamp(milestoneParam, 1, MAX_TOTAL_LEVEL);
        final int totalActual = clamp(totalActualParam, 1, MAX_TOTAL_LEVEL);

        final int count = clamp(countParam, 1, 24);

        switch (preset)
        {
            case SKILL_PLUS_ONE:
            {
                int base = (client.getGameState() == GameState.LOGGED_IN)
                    ? client.getRealSkillLevel(s1)
                    : 1;
                int to = Math.min(99, base + 1);

                sendToastBatch(false, new ToastItem[] {
                    ToastItem.structured("LEVEL_UP", 40, 6000, n1, to, null)
                });
                break;
            }

            case SKILL_99:
            {
                sendToastBatch(true, new ToastItem[] {
                    ToastItem.structured("LEVEL_99", 80, 10000, n1, 99, null)
                });
                break;
            }

            case SKILL_200M:
            {
                ToastItem t = new ToastItem();
                t.kind = "LEVEL_99"; // Fakes LEVEL_99 so the ESP32 draws the skill icon
                t.prio = 90;
                t.ms = 10000;
                t.skill = n1;
                t.msg = "Congratulations!\nYou reached 200,000,000 XP in " + n1 + "!";
                sendToastBatch(true, new ToastItem[] { t });
                break;
            }

            case TOTAL_MILESTONE:
            {
                int actual = Math.max(totalActual, milestone);
                sendToastBatch(true, new ToastItem[] {
                    ToastItem.structured("TOTAL_LEVEL", 70, 9000, null, milestone, actual)
                });
                break;
            }

            case LEVELUP_AND_99:
            {
                sendToastBatch(true, new ToastItem[] {
                    ToastItem.structured("LEVEL_UP", 40, 6000, n1, 50, null),
                    ToastItem.structured("LEVEL_99", 80, 10000, n2, 99, null)
                });
                break;
            }

            case LEVELUP_AND_MILESTONE:
            {
                int actual = Math.max(totalActual, milestone);
                sendToastBatch(true, new ToastItem[] {
                    ToastItem.structured("LEVEL_UP", 40, 6000, n1, 50, null),
                    ToastItem.structured("TOTAL_LEVEL", 70, 9000, null, milestone, actual)
                });
                break;
            }

            case NINETY_NINE_AND_MILESTONE:
            {
                int actual = Math.max(totalActual, milestone);
                sendToastBatch(true, new ToastItem[] {
                    ToastItem.structured("LEVEL_99", 80, 10000, n1, 99, null),
                    ToastItem.structured("TOTAL_LEVEL", 70, 9000, null, milestone, actual)
                });
                break;
            }

            case NINETY_NINE_AND_MAX_TOTAL:
            {
                // ESP32 “MAX_TOTAL collapses all” logic should win; this tests that rule.
                sendToastBatch(true, new ToastItem[] {
                    ToastItem.structured("LEVEL_99", 80, 10000, n1, 99, null),
                    ToastItem.structured("MAX_TOTAL", 100, 10000, null, null, MAX_TOTAL_LEVEL)
                });
                break;
            }

            case FIVE_RANDOM_LEVEL_UPS:
            {
                java.util.Random rng = new java.util.Random(System.currentTimeMillis());
                Skill[] skills = SKILL_TO_ID.keySet().toArray(new Skill[0]);

                java.util.ArrayList<ToastItem> out = new java.util.ArrayList<>(count);
                for (int i = 0; i < count; i++)
                {
                    Skill s = skills[rng.nextInt(skills.length)];
                    String name = skillName(s);
                    int lvl = 2 + rng.nextInt(98); // 2..99
                    out.add(ToastItem.structured("LEVEL_UP", 40, 6000, name, lvl, null));
                }

                sendToastBatch(false, out.toArray(new ToastItem[0]));
                break;
            }

            case QUEUE_OVERFLOW:
            {
                java.util.ArrayList<ToastItem> out = new java.util.ArrayList<>(20);
                for (int i = 1; i <= 20; i++)
                {
                    out.add(ToastItem.of("OTHER", 10, 1500, "QUEUE TEST " + i));
                }
                sendToastBatch(false, out.toArray(new ToastItem[0]));
                break;
            }

            case PREEMPT_LONG_WITH_99:
            {
                sendToastBatch(false, new ToastItem[] {
                    ToastItem.of("OTHER", 10, 10000, "LOW PRIO LONG TOAST (should be preempted)")
                });

                scheduleClientToast(500, () -> sendToastBatch(true, new ToastItem[] {
                    ToastItem.structured("LEVEL_99", 80, 10000, n1, 99, null)
                }));
                break;
            }

            case PREEMPT_LONG_WITH_MILESTONE:
            {
                int actual = Math.max(totalActual, milestone);

                sendToastBatch(false, new ToastItem[] {
                    ToastItem.of("OTHER", 10, 10000, "LOW PRIO LONG TOAST (should be preempted)")
                });

                scheduleClientToast(500, () -> sendToastBatch(true, new ToastItem[] {
                    ToastItem.structured("TOTAL_LEVEL", 70, 9000, null, milestone, actual)
                }));
                break;
            }

            case MIXED_PRIORITY_ORDERING:
            {
                // One batch with low/med/high prio to validate ordering and ESP32 formatting.
                sendToastBatch(true, new ToastItem[] {
                    ToastItem.of("OTHER", 10, 6000, "LOW"),
                    ToastItem.structured("LEVEL_UP", 40, 6000, n1, 42, null),
                    ToastItem.structured("LEVEL_99", 80, 10000, n2, 99, null)
                });
                break;
            }

            default:
                break;
        }
    }

    private static int clamp(int v, int lo, int hi)
    {
        return Math.max(lo, Math.min(hi, v));
    }

    private int cachedQuestsCompleted = -1;
    private int cachedQuestsTotal = -1;

    private int cachedCombatTasksCompleted = -1;
    private int cachedCombatTasksTotal = -1;

    private int cachedDiariesCompleted = -1;
    private int cachedDiariesTotal = -1;

    private void checkQuestWidgets()
    {
        if (client.getGameState() != GameState.LOGGED_IN) return;

        net.runelite.api.widgets.Widget[] roots = client.getWidgetRoots();
        if (roots == null) return;

        for (net.runelite.api.widgets.Widget root : roots)
        {
            scanWidgetForQuests(root);
        }
    }

    private void scanWidgetForQuests(net.runelite.api.widgets.Widget w)
    {
        if (w == null) return;

        checkWidgetTextForQuests(w);

        if (w.getStaticChildren() != null) {
            for (net.runelite.api.widgets.Widget c : w.getStaticChildren()) {
                scanWidgetForQuests(c);
            }
        }
        if (w.getDynamicChildren() != null) {
            for (net.runelite.api.widgets.Widget c : w.getDynamicChildren()) {
                scanWidgetForQuests(c);
            }
        }
        if (w.getNestedChildren() != null) {
            for (net.runelite.api.widgets.Widget c : w.getNestedChildren()) {
                scanWidgetForQuests(c);
            }
        }
    }

    private void checkWidgetTextForQuests(net.runelite.api.widgets.Widget w)
    {
        String text = w.getText();
        if (text == null || text.isEmpty() || !text.contains("/")) return;

        // Strips any color tags like <col=ff981f>
        String clean = text.replaceAll("<[^>]*>", "").trim();

        // Ignore "Quest Points: 343/343" to stop it from overwriting the real quest count
        if (clean.toLowerCase().contains("points")) return;

        java.util.regex.Matcher m = java.util.regex.Pattern.compile("(\\d+)\\s*/\\s*(\\d+)").matcher(clean);
        if (m.find())
        {
            int comp = Integer.parseInt(m.group(1));
            int tot = Integer.parseInt(m.group(2));

            if (tot <= 0 || comp > tot) return;

            // Combat Tasks (Total is 655. Bound 500-750 safely avoids Diaries at 492 and Music at 853+)
            if (tot >= 500 && tot <= 750) {
                if (cachedCombatTasksCompleted != comp || cachedCombatTasksTotal != tot) {
                    cachedCombatTasksCompleted = comp;
                    cachedCombatTasksTotal = tot;
                    enqueueImmediateHeartbeatNow();
                }
            }
            // Quests (Total is 184. Bound 130-195)
            else if (tot >= 130 && tot <= 195) {
                if (cachedQuestsCompleted != comp || cachedQuestsTotal != tot) {
                    cachedQuestsCompleted = comp;
                    cachedQuestsTotal = tot;
                    enqueueImmediateHeartbeatNow();
                }
            }
            // Diaries (Total is 492. Bound 400-499)
            else if (tot >= 400 && tot <= 499) {
                if (cachedDiariesCompleted != comp || cachedDiariesTotal != tot) {
                    cachedDiariesCompleted = comp;
                    cachedDiariesTotal = tot;
                    enqueueImmediateHeartbeatNow();
                }
            }
        }
    }

