    // OSRS time played
    // --------------------
    private void updateTimePlayedTracking()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        String player = getPushPlayer();
        if (player == null || player.trim().isEmpty())
        {
            return;
        }

        String normalizedPlayer = normalizePlayerForMatch(player);

        // A different RuneScape character has logged in.
        // Never carry another character's playtime across.
        if (!normalizedPlayer.equals(trackedTimePlayedPlayer))
        {
            trackedTimePlayedPlayer = normalizedPlayer;
            trackedTimePlayedMinutes = -1;
            trackedTimePlayedTenths = 0;
        }

        int authoritativeMinutes = client.getVarcIntValue(TIME_PLAYED_VARC);

        // The game occasionally refreshes VarC 526.
        // Whenever it is ahead of us, use it as the authoritative baseline.
        if (authoritativeMinutes > 0
            && (trackedTimePlayedMinutes < 0
                || authoritativeMinutes > trackedTimePlayedMinutes))
        {
            trackedTimePlayedMinutes = authoritativeMinutes;
            trackedTimePlayedTenths = 0;
            return;
        }

        // If VarC 526 has not populated yet, do not invent a value.
        if (trackedTimePlayedMinutes < 0)
        {
            return;
        }

        // One RuneScape game tick is approximately 0.6 seconds.
        trackedTimePlayedTenths += 6;

        if (trackedTimePlayedTenths >= 600)
        {
            trackedTimePlayedMinutes += trackedTimePlayedTenths / 600;
            trackedTimePlayedTenths %= 600;
        }
    }

    private Integer getHoursPlayedForPush()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }

        String player = getPushPlayer();
        if (player == null || player.trim().isEmpty())
        {
            return null;
        }

        // Make sure the tracked time actually belongs to the currently
        // logged-in RuneScape character.
        if (!normalizePlayerForMatch(player).equals(trackedTimePlayedPlayer))
        {
            return null;
        }

        if (trackedTimePlayedMinutes < 0)
        {
            return null;
        }

        return trackedTimePlayedMinutes / 60;
    }

    private void attachHoursPlayed(PushPayload payload)
    {
        if (payload == null)
        {
            return;
        }

        Integer hoursPlayed = getHoursPlayedForPush();

        if (hoursPlayed != null)
        {
            payload.hoursPlayed = hoursPlayed;
        }
    }

    private void attachQuests(PushPayload payload)
    {
        if (payload == null || client.getGameState() != GameState.LOGGED_IN) return;

        if (cachedQuestsTotal > 0 && cachedQuestsCompleted >= 0)
        {
            payload.questsCompleted = cachedQuestsCompleted;
            payload.questsTotal = cachedQuestsTotal;
        }
    }

    private void attachCombatTasks(PushPayload payload)
    {
        if (payload == null || client.getGameState() != GameState.LOGGED_IN) return;

        if (cachedCombatTasksTotal > 0 && cachedCombatTasksCompleted >= 0)
        {
            payload.combatTasksCompleted = cachedCombatTasksCompleted;
            payload.combatTasksTotal = cachedCombatTasksTotal;
        }
    }

    private void attachDiaries(PushPayload payload)
    {
        if (payload == null || client.getGameState() != GameState.LOGGED_IN) return;

        if (cachedDiariesTotal > 0 && cachedDiariesCompleted >= 0)
        {
            payload.diariesCompleted = cachedDiariesCompleted;
            payload.diariesTotal = cachedDiariesTotal;
        }
    }

    private void attachCollectionLog(PushPayload payload)
    {
        if (payload == null)
        {
            return;
        }

        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        int count = client.getVarpValue(
            VarPlayerID.COLLECTION_COUNT
        );

        int max = client.getVarpValue(
            VarPlayerID.COLLECTION_COUNT_MAX
        );

        // Do not send an obviously uninitialized/invalid pair.
        // count == 0 is valid for a new account.
        if (count < 0 || max <= 0 || count > max)
        {
            return;
        }

        payload.collectionLogCount = count;
        payload.collectionLogMax = max;
    }

