    private String normalizePlayerForMatch(String s)
    {
        if (s == null)
        {
            return "";
        }

        String n = s.trim().toLowerCase().replace('_', ' ');
        while (n.contains("  "))
        {
            n = n.replace("  ", " ");
        }
        return n;
    }

