    private void doPing()
    {
        HttpUrl url = buildUrl("ping");
        if (url == null)
        {
            uiSetPanelStatus("Ping failed: invalid device URL.");
            return;
        }

        uiSetPanelStatus("Pinging device...");

        log.info("AUTO CAT probe URL: {}", url);
