    // --------------------
    // Bank total compute
    // --------------------
    private long computeBankTotal()
    {
        ItemContainer bank = client.getItemContainer(InventoryID.BANK);
        if (bank == null)
        {
            return (lastSentBankTotal >= 0) ? lastSentBankTotal : 0;
        }

        long total = 0;
        for (Item it : bank.getItems())
        {
            if (it == null) continue;
            int id = it.getId();
            int qty = it.getQuantity();
            if (id <= 0 || qty <= 0) continue;

            long price = itemManager.getItemPrice(id);
            total += (long) price * (long) qty;
        }
        return total;
    }

    // --------------------
    // Coalescing sender with retry/backoff (skills/bank)
    // --------------------
    private void enqueue(PendingKind kind, HttpUrl url, PushPayload payload)
    {
        synchronized (sendLock)
        {
            pending.put(kind, payload);

            if (retryFuture == null && inFlightPayload == null)
            {
                sendNextLocked();
            }
        }
    }

    private void sendNextLocked()
    {
        if (inFlightPayload != null)
        {
            return;
        }

        PendingKind nextKind = pickNextKindLocked();
        if (nextKind == null)
        {
            return;
        }

        PushPayload p = pending.get(nextKind);
        if (p == null)
        {
            return;
        }

        HttpUrl url = buildUrl("push");
        if (url == null)
        {
            scheduleRetryLocked();
            return;
        }

        inFlightKind = nextKind;
        inFlightPayload = p;

        log.info("SEND START kind={}", nextKind);
        postAsync(url, p);
    }

    private PendingKind pickNextKindLocked()
    {
        if (pending.containsKey(PendingKind.CONFIG)) return PendingKind.CONFIG;
        if (pending.containsKey(PendingKind.TOAST)) return PendingKind.TOAST;
        if (pending.containsKey(PendingKind.SNAPSHOT)) return PendingKind.SNAPSHOT;
        if (pending.containsKey(PendingKind.LEVEL)) return PendingKind.LEVEL;
        if (pending.containsKey(PendingKind.BANK))  return PendingKind.BANK;
        if (pending.containsKey(PendingKind.XP))    return PendingKind.XP;
        if (pending.containsKey(PendingKind.HEARTBEAT)) return PendingKind.HEARTBEAT;
        return null;
    }


    private void postAsync(HttpUrl url, PushPayload payload)
    {
        String json = gson.toJson(payload);
        RequestBody body = RequestBody.create(JSON, json);
        Request req = new Request.Builder().url(url).post(body).build();

        http.newCall(req).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException ex)
            {
                onSendResult(false, 0, ex.toString());
            }

            @Override
            public void onResponse(Call call, Response resp) throws IOException
            {
                int code;
                try (Response r = resp)
                {
                    code = r.code();
                }
                boolean ok = (code >= 200 && code < 300);
                onSendResult(ok, code, null);
            }
        });
    }

    private void onSendResult(boolean ok, int httpCode, String err)
    {
        synchronized (sendLock)
        {
            PendingKind sentKind = inFlightKind;
            PushPayload sentPayload = inFlightPayload;

            inFlightKind = null;
            inFlightPayload = null;

            if (ok)
            {
                uiSetPanelStatus("Connected");
                log.info("SEND OK kind={} httpCode={}", sentKind, httpCode);

                PushPayload stillPending = pending.get(sentKind);
                if (stillPending == sentPayload)
                {
                    pending.remove(sentKind);
                }

                consecutiveFailures = 0;
                backoffMs = RETRY_BACKOFF_BASE_MS;

                if (retryFuture != null)
                {
                    retryFuture.cancel(false);
                    retryFuture = null;
                }

                sendNextLocked();
                return;
            }

            boolean nonRetryable403 =
                httpCode == 403
                    && sentKind != PendingKind.CONFIG;

            if (nonRetryable403)
            {
                PushPayload stillPending = pending.get(sentKind);
                if (stillPending == sentPayload)
                {
                    pending.remove(sentKind);
                }

                consecutiveFailures = 0;
                backoffMs = RETRY_BACKOFF_BASE_MS;

                log.info("ESP32 push rejected with HTTP 403 for {}. Dropping without retry.", sentKind);

                sendNextLocked();
                return;
            }

            consecutiveFailures++;
            if (consecutiveFailures >= 2) {
                uiSetPanelStatus("Connection Lost / Searching...");
            }
            if (httpCode != 0)
            {
                log.info("ESP32 push failed HTTP {}", httpCode);
            }
            else if (err != null)
            {
                log.info("ESP32 push failed: {}", err);
            }

            backoffMs = Math.min(backoffMs * 2, RETRY_BACKOFF_MAX_MS);
            scheduleRetryLocked();
        }
    }

    private void scheduleRetryLocked()
    {
        if (retryFuture != null && !retryFuture.isDone())
        {
            return;
        }

        long delay = backoffMs;
        retryFuture = executor.schedule(() ->
        {
            synchronized (sendLock)
            {
                retryFuture = null;
                if (inFlightPayload == null)
                {
                    sendNextLocked();
                }
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    private static final int MAX_TOTAL_LEVEL = 99 * SKILL_TO_ID.size();

    private void startUdpDiscovery() {
            if (udpDiscoveryFuture != null) return;
            udpDiscoveryFuture = executor.scheduleAtFixedRate(() -> {
                String deviceId = config.deviceId();
                if (deviceId == null || deviceId.isEmpty()) return;

                boolean needsDiscovery = false;

                // Check if we are currently failing to reach the device
                synchronized (sendLock) {
                    if (consecutiveFailures >= 2) {
                        needsDiscovery = true;
                    }
                }

                // Also discover if the host IP is completely empty
                String host = config.deviceHost();
                if (host == null || host.trim().isEmpty()) {
                    needsDiscovery = true;
                }

                if (needsDiscovery) {
                    uiSetPanelStatus("Searching...");
                    new Thread(() -> broadcastUdp("FIND:" + deviceId)).start();
                }
            }, 0, 30, TimeUnit.SECONDS);
        }

    public void triggerPairing(String pin) {
        new Thread(() -> broadcastUdp("PAIR:" + pin)).start();
    }

    private void broadcastUdp(String payload) {
        try (DatagramSocket socket = new DatagramSocket()) {
            socket.setBroadcast(true);
            byte[] buffer = payload.getBytes();
            InetAddress address = InetAddress.getByName("255.255.255.255");
            DatagramPacket packet = new DatagramPacket(buffer, buffer.length, address, 8081);
            socket.send(packet);

            byte[] recvBuf = new byte[256];
            DatagramPacket recvPacket = new DatagramPacket(recvBuf, recvBuf.length);
            socket.setSoTimeout(3000);
            socket.receive(recvPacket);

            String response = new String(recvPacket.getData(), 0, recvPacket.getLength()).trim();
            log.info("UDP Response: " + response);

        if (response.startsWith("ACK,") || response.startsWith("FOUND,")) {
                        String[] parts = response.split(",");
                        String ip = "";
                        if (response.startsWith("ACK,") && parts.length >= 3) {
                            String mac = parts[1];
                            ip = parts[2];
                            configManager.setConfiguration(CONFIG_GROUP, "deviceId", mac);
                        } else if (response.startsWith("FOUND,") && parts.length >= 2) {
                            ip = parts[1];
                        }

                    if (!ip.isEmpty() && !ip.equals(config.deviceHost())) {
                    configManager.setConfiguration(CONFIG_GROUP, "deviceHost", ip);
                    log.info("Updated device IP to: " + ip);
                }
                uiSetPanelStatus("Connected");
            }
        } catch (SocketTimeoutException e) {
            log.debug("UDP Discovery timeout (no device found)");
            if (config.deviceId() != null && !config.deviceId().isEmpty()) {
                uiSetPanelStatus("Searching...");
            }
        } catch (Exception e) {
            log.warn("UDP Broadcast failed", e);
        }
    }

